#!/usr/bin/env python3
"""v13 = v12 + notation-clash and domain-of-application corrections.
Every replacement is asserted to match the stated number of times."""
from pathlib import Path
import re, sys

ROOT = Path(__file__).resolve().parents[1]
SRC = ROOT.parent / 'v12' / 'manuscript' / 'prime_corrected_clock_v12.tex'
DST = ROOT / 'manuscript' / 'prime_corrected_clock_v13.tex'
text = SRC.read_text()
BODY0 = text.index('\\begin{document}')

def rep(old, new, cnt=1):
    """Replacement in the body (the hover-preview macros of the preamble are regenerated by the build)."""
    global text
    head, body = text[:BODY0], text[BODY0:]
    n = body.count(old)
    if cnt is None: cnt = n if n else -1
    assert n == cnt, f'{n} matches (expected {cnt}) for: {old[:90]!r}'
    text = head + body.replace(old, new)

def region(start_marker, end_marker, pairs):
    """Plain replacements restricted to text[start:end]."""
    global text
    a = text.index(start_marker, BODY0)
    b = text.index(end_marker, a)
    seg = text[a:b]
    for old, new, cnt in pairs:
        n = seg.count(old)
        if cnt is None: cnt = n if n else -1
        assert n == cnt, f'region {start_marker[:30]!r}: {n} (expected {cnt}) for {old!r}'
        seg = seg.replace(old, new)
    text = text[:a] + seg + text[b:]

